def replace_lab(content, lab_id, new_lab_str):
    start_idx = content.find(f"{{id:'{lab_id}'")
    if start_idx == -1: return content
    
    exp_idx = content.find("explanation:", start_idx)
    end_idx = content.find("},", exp_idx) + 2
    
    return content[:start_idx] + new_lab_str + content[end_idx:]

with open('src/pages/labs.tsx', 'r') as f:
    content = f.read()

lab_50 = "{id:'oop-polymorphism',title:'50 · OOP Polymorphism: The Senior Cloud Interface',prompt:'(Interview Scenario) You are given a junior script that raises NotImplementedError. As a senior, upgrade this to a production-ready Abstract Base Class. You must use `abc.ABC`, `@abstractmethod`, `logging`, strict type hints, a `dataclass` for configuration, and robust error handling.',starter:`import logging\\nfrom abc import ABC, abstractmethod\\nfrom dataclasses import dataclass\\n\\n# TODO: Define a frozen dataclass NodeConfig(instance_type: str, region: str)\\n# TODO: Define CloudProvider(ABC) with abstractmethod provision_node(self, config: NodeConfig) -> str\\n# TODO: Implement AWSProvider and GCPProvider\\n# TODO: Implement orchestration function scale_out(provider, config) with logging\\n`,expected:\"Proper abstract base classes and logging\",tests:`import logging\\nimport sys\\nfrom abc import ABC\\n\\nassert issubclass(CloudProvider, ABC), \"CloudProvider must inherit from abc.ABC\"\\nassert \"provision_node\" in CloudProvider.__abstractmethods__, \"provision_node must be an @abstractmethod\"\\n\\nconfig = NodeConfig(instance_type=\"gpu.large\", region=\"us-east-1\")\\naws = AWSProvider()\\nassert \"aws\" in aws.provision_node(config).lower()\\n\\nprint('PASS')`,hint:'Use `from abc import ABC, abstractmethod`. Pass a dataclass into the method instead of raw strings. Use `logging.getLogger(__name__)`.',solution:`import logging\\nfrom abc import ABC, abstractmethod\\nfrom dataclasses import dataclass\\n\\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s - %(levelname)s - %(message)s\")\\nlogger = logging.getLogger(__name__)\\n\\n@dataclass(frozen=True)\\nclass NodeConfig:\\n    instance_type: str\\n    region: str\\n\\nclass CloudProvider(ABC):\\n    @abstractmethod\\n    def provision_node(self, config: NodeConfig) -> str:\\n        \\\"\\\"\\\"Provisions a node and returns the instance ID.\\\"\\\"\\\"\\n        pass\\n\\nclass AWSProvider(CloudProvider):\\n    def provision_node(self, config: NodeConfig) -> str:\\n        logger.info(f\"Provisioning AWS EC2 {config.instance_type} in {config.region}\")\\n        return f\"i-aws-{config.instance_type}\"\\n\\nclass GCPProvider(CloudProvider):\\n    def provision_node(self, config: NodeConfig) -> str:\\n        logger.info(f\"Provisioning GCP Compute {config.instance_type} in {config.region}\")\\n        return f\"gcp-{config.instance_type}\"\\n\\ndef scale_out(provider: CloudProvider, config: NodeConfig) -> str:\\n    try:\\n        node_id = provider.provision_node(config)\\n        logger.info(f\"Successfully scaled out: {node_id}\")\\n        return node_id\\n    except Exception as e:\\n        logger.error(f\"Failed to scale out: {e}\")\\n        raise\\n\\nif __name__ == '__main__':\\n    config = NodeConfig(instance_type=\"gpu.large\", region=\"us-east-1\")\\n    scale_out(AWSProvider(), config)\\n`,explanation:'In a senior interview, simply raising NotImplementedError is not enough. You must demonstrate interface enforcement (ABC), immutability (frozen dataclasses), observability (structured logging), and proper type hints. This proves your code can safely scale across a team of developers.'},"

lab_51 = "{id:'decorator-timer',title:'51 · Execution Timer: Production Decorator',prompt:'(Interview Scenario) A junior engineer wrote a timer decorator using `time.time()` and `print()`. Upgrade this to senior level: Use `time.perf_counter()` for high-resolution timing, `logging` for observability, `functools.wraps` to preserve docstrings, and a `try/finally` block so the timer still logs even if the function crashes.',starter:`import logging\\nimport time\\nfrom functools import wraps\\nfrom typing import Callable, Any\\n\\nlogging.basicConfig(level=logging.INFO)\\nlogger = logging.getLogger(__name__)\\n\\n# TODO: Implement time_execution decorator\\n`,expected:\"Logs high-res duration regardless of exceptions\",tests:`import io\\nimport logging\\n\\nlog_capture = io.StringIO()\\nch = logging.StreamHandler(log_capture)\\nlogger.addHandler(ch)\\n\\n@time_execution\\ndef fail_task():\\n    raise ValueError(\"Crashing!\")\\n\\ntry:\\n    fail_task()\\nexcept ValueError:\\n    pass\\n\\noutput = log_capture.getvalue()\\nassert \"executed in\" in output.lower(), \"Must log duration even if function raises an exception!\"\\nprint('PASS')`,hint:'Use `start = time.perf_counter()`. Wrap the function call in `try:` and do the timing/logging in a `finally:` block.',solution:`import logging\\nimport time\\nfrom functools import wraps\\nfrom typing import Callable, Any\\n\\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s - %(levelname)s - %(message)s\")\\nlogger = logging.getLogger(__name__)\\n\\ndef time_execution(func: Callable) -> Callable:\\n    @wraps(func)\\n    def wrapper(*args: Any, **kwargs: Any) -> Any:\\n        start_time = time.perf_counter()\\n        try:\\n            return func(*args, **kwargs)\\n        finally:\\n            duration = time.perf_counter() - start_time\\n            logger.info(f\"Function '{func.__name__}' executed in {duration:.4f}s\")\\n    return wrapper\\n\\nif __name__ == '__main__':\\n    @time_execution\\n    def heavy_task():\\n        time.sleep(0.1)\\n        return \"Done\"\\n    \\n    heavy_task()\\n`,explanation:'Senior engineers know that `time.time()` is subject to NTP clock skew (time can go backward on a server!). They use `time.perf_counter()`. They also use `try/finally` to guarantee metrics are emitted even if the task fails, and use `logging` instead of `print` so the output can be scraped by monitoring agents.'},"

lab_46 = "{id:'async-retry',title:'46 · Async Retry with Full Jitter',prompt:'(Interview Scenario) A junior engineer wrote a simple linear retry loop. Upgrade it: Add standard `logging`, catch specific custom exceptions rather than `Exception`, and implement AWS-style \"Full Jitter\" exponential backoff (`random.uniform(0, base_delay * 2**attempt)`) to prevent thundering herds on recovery.',starter:`import asyncio\\nimport logging\\nimport random\\nfrom typing import Callable, Any, Awaitable\\n\\nlogging.basicConfig(level=logging.WARNING)\\nlogger = logging.getLogger(__name__)\\n\\nclass UpstreamAPIError(Exception):\\n    pass\\n\\n# TODO: Implement fetch_with_retry using full jitter backoff\\n`,expected:\"Logs warnings, uses jitter, and raises custom exception\",tests:`import time\\n\\nasync def fail_func():\\n    raise UpstreamAPIError(\"Test\")\\n\\nstart = time.time()\\ntry:\\n    await fetch_with_retry(fail_func, max_attempts=3, base_delay=0.1)\\nexcept UpstreamAPIError:\\n    pass\\n\\nduration = time.time() - start\\nassert duration > 0.05, \"Backoff was too fast\"\\nprint('PASS')`,hint:'Full Jitter formula: `sleep_time = random.uniform(0, base_delay * (2 ** (attempt - 1)))`. Catch `UpstreamAPIError`, log it, sleep, and if it is the last attempt, re-raise.',solution:`import asyncio\\nimport logging\\nimport random\\nfrom typing import Callable, Any, Awaitable\\n\\nlogging.basicConfig(level=logging.WARNING, format=\"%(asctime)s - %(levelname)s - %(message)s\")\\nlogger = logging.getLogger(__name__)\\n\\nclass UpstreamAPIError(Exception):\\n    pass\\n\\nasync def fetch_with_retry(func: Callable[[], Awaitable[Any]], max_attempts: int = 3, base_delay: float = 0.1) -> Any:\\n    for attempt in range(1, max_attempts + 1):\\n        try:\\n            return await func()\\n        except UpstreamAPIError as e:\\n            if attempt == max_attempts:\\n                logger.error(f\"Failed after {max_attempts} attempts. Last error: {e}\")\\n                raise\\n            \\n            # Full Jitter Exponential Backoff\\n            sleep_time = random.uniform(0, base_delay * (2 ** (attempt - 1)))\\n            logger.warning(f\"Attempt {attempt} failed. Retrying in {sleep_time:.2f}s...\")\\n            await asyncio.sleep(sleep_time)\\n\\nif __name__ == '__main__':\\n    async def mock_network_call():\\n        raise UpstreamAPIError(\"Connection Reset\")\\n    \\n    asyncio.run(fetch_with_retry(mock_network_call))\\n`,explanation:'In distributed systems, if an API goes down and 10,000 clients retry exactly 1 second later, the returning API is instantly DDoSed (Thundering Herd). Senior engineers introduce \"Jitter\" (randomness) to smooth out the retry spikes. They also catch specific exceptions rather than broad `Exception`, which would wrongly mask `KeyboardInterrupt` or `SyntaxError`.'},"

content = replace_lab(content, 'oop-polymorphism', lab_50)
content = replace_lab(content, 'decorator-timer', lab_51)
content = replace_lab(content, 'async-retry', lab_46)

with open('src/pages/labs.tsx', 'w') as f:
    f.write(content)
